mapper.update:
update agent_instance
   set status = 'OFFLINE',
       updated_at = #{now}
 where status in ('ACTIVE', 'ONLINE', 'STOPPING')
   and lease_expires_at is not null
   and lease_expires_at <= #{now}

update attach_executor
   set status = 'OFFLINE',
       updated_at = #{now}
 where status in ('ACTIVE', 'ONLINE')
   and lease_expires_at is not null
   and lease_expires_at <= #{now}

update instance
   set status = 'OFFLINE',
       updated_at = #{now}
 where status in ('ACTIVE', 'ONLINE')
   and lease_expires_at is not null
   and lease_expires_at <= #{now}

mapper.delete:
delete from attach_executor_command
 where status in ('SUCCEEDED', 'FAILED', 'CANCELLED', 'EXPIRED')
   and coalesce(finished_at, lease_expires_at, updated_at, created_at) <= #{cutoff}

delete from agent_command
 where status in ('ACKED', 'FAILED', 'CANCELLED', 'EXPIRED')
   and coalesce(completed_at, lease_expires_at, updated_at, created_at) <= #{cutoff}

delete from sidecar_instance s
 where coalesce(s.last_heartbeat_at, s.updated_at, s.created_at) <= #{cutoff}
   and (
       s.status = 'OFFLINE'
       or exists (
           select 1
             from instance i
            where i.id = s.instance_id
              and i.status = 'OFFLINE'
              and coalesce(i.lease_expires_at, i.last_seen_at, i.updated_at, i.created_at) <= #{cutoff}
       )
   )
   and not exists (select 1 from agent_instance a where a.sidecar_id = s.id)

delete from attach_executor_target t
 where t.status = 'OFFLINE'
   and coalesce(t.last_seen_at, t.updated_at, t.created_at) <= #{cutoff}
